const BAJI_INFO={id:"baji-rout",title:"Baji Rout",quickStats:[{label:"Born",value:"1926, Nilakanthapur",icon:"📍"},{label:"Died",value:"October 11, 1938",icon:"🕯️"},{label:"Age at Martyrdom",value:"12 Years",icon:"🌟"},{label:"Region",value:"Odisha (then Orissa)",icon:"🗺️"},{label:"Role",value:"Boatman & Village Volunteer",icon:"🛶"},{label:"Remembered As",value:"One of India's Youngest Martyrs",icon:"🇮🇳"}]},HISTORY_TEXT={title:"A Boatman's Son in Colonial Odisha",paragraphs:["Baji Rout was born in 1926 in the village of Nilakanthapur in the princely state of Dhenkanal, in present-day Odisha. He came from a family of boatmen and worked ferrying passengers across the local river from a young age.","In the 1930s, the princely state of Dhenkanal was the site of growing unrest as local peasants organized the Praja Mandal movement, protesting oppressive taxation and forced labor imposed by the state administration. Popular resistance grew across many villages in the region.","On the night of October 11, 1938, state police arrived at the riverbank where young Baji Rout was on duty as a boatman and volunteer, demanding he ferry them across the river to suppress protesting villagers. Baji Rout refused to cooperate with the police in their mission against his own community.","In response to his refusal, the police opened fire, and Baji Rout was fatally shot. He died that night, becoming, at twelve years old, one of the youngest known martyrs of India's freedom struggle. His death became a rallying point for the Praja Mandal movement in Dhenkanal and is remembered in Odisha as a symbol of courage and sacrifice."]},TIMELINE_EVENTS=[{era:"1926",title:"Born in Nilakanthapur",description:"Baji Rout was born into a boatman family in the princely state of Dhenkanal, Odisha."},{era:"1930s",title:"Rise of the Praja Mandal Movement",description:"Growing unrest in Dhenkanal as villagers organized against oppressive state taxation and forced labor."},{era:"October 11, 1938",title:"Refusal at the Riverbank",description:"Baji Rout, on duty as a young boatman, refused to ferry state police across the river to suppress protesting villagers."},{era:"October 11, 1938",title:"Martyrdom",description:"Police opened fire on him for his refusal; Baji Rout was fatally shot at the age of twelve."},{era:"Post-1938",title:"Symbol of the Movement",description:"His death galvanized the Praja Mandal movement in Dhenkanal and became remembered across Odisha as an act of courage."}],STRUGGLE_POINTS=[{title:"The Praja Mandal Movement",description:"A popular movement in princely states like Dhenkanal, organizing peasants against oppressive taxation, forced labor, and autocratic administration."},{title:"Local Resistance in Dhenkanal",description:"Villagers across the Dhenkanal region actively resisted state policies, drawing a strong police response."},{title:"An Act of Quiet Defiance",description:"Baji Rout's refusal to assist police against his own community, despite being a child, exemplified the widespread resolve of the movement."},{title:"Ripple Effect",description:"His death intensified public anger and support for the Praja Mandal cause across the region."}],MEMORIALS=[{title:"Baji Rout Chhatrabas",description:"Student hostels and institutions named in his honor exist in parts of Odisha, commemorating his sacrifice."},{title:"Statues and Memorials",description:"Memorials and statues dedicated to Baji Rout have been erected in Odisha, particularly in the Dhenkanal region."},{title:"Regional Commemoration",description:"His memory is honored annually in parts of Odisha as a symbol of youthful courage in the freedom struggle."}],GALLERY_QUERIES=["Dhenkanal Odisha riverbank landscape","Odisha princely state historical","Mahanadi river boats Odisha"],REFERENCES=[{text:"Government of Odisha — historical records on the Praja Mandal movement.",link:"#"},{text:"Pati, B. — historical studies on princely state resistance movements in Odisha.",link:"#"},{text:"Regional archives on the Dhenkanal Praja Mandal uprising.",link:"#"}];